if (typeof msg.payload !== 'object' ||
    typeof msg.payload.hmi !== 'object' ||
    typeof msg.payload.project !== 'string'
) {
    return;
}

msg.filename = '/data/projects/' + msg.payload.project + '/package.json'

msg.payload.app = {
    'title': 'DKNR',
    'version' : '0.0',
    'git': ''
}

global.set('describe', msg.payload, 'memoryOnly');

return msg;

delete msg.filename;

if (typeof global.get('describe', 'memoryOnly') !== 'object') {
    global.set('describe', { }, 'memoryOnly')
}

let describe = global.get('describe', 'memoryOnly');

if (typeof msg.payload === 'object') {
    describe.app = {
        'title': msg.payload.description.slice(5) || '',
        'version' : msg.payload.version || '',
        'git': msg.payload.name || ''
    };
}

describe.mqtt = {
    'host': '',
    'port': 1883,
    'username': '',
    'password': '',
    'topic': 'dknr',
    'enabled': false,
    'homeassistant': 'homeassistant',
    'nukimqtt': false
};

return msg;

msg.broker = {};

let mqtt = global.get('mqtt', 'default');
if (typeof mqtt == 'object' && mqtt.enabled == true) {
    if (mqtt.host.length > 0
        && mqtt.port > 0
        && mqtt.topic.length > 0
    ) {
        msg.broker.broker = mqtt.host;
        msg.broker.port = mqtt.port;
        if (mqtt.username.length > 0 && mqtt.password.length > 0) {
            msg.broker.username = mqtt.username;
            msg.broker.password = mqtt.password;
        }

        msg.broker.force = true;
        msg.action = 'connect';
        node.status({fill:"green",shape:"ring",text:"settings ok"});

        return msg;
    } else {
        global.set('mqtt["enabled"]', false, 'default');
        node.status({ fill: "red", shape: "ring", text: "settings ko" });
    }
}

msg.action = 'disconnect';

return msg;

// Subscribe to DKNR commands topic (and to Nuki native MQTT topic if enabled)

msg.broker = {};

const mqtt = global.get('mqtt', 'default');
const source = 'nuki';

if (typeof mqtt == 'object' && mqtt.enabled == true) {
    if (mqtt.host.length > 0
        && mqtt.port > 0
        && mqtt.topic.length > 0
    ) {
        msg.broker.broker = mqtt.host;
        msg.broker.port = mqtt.port;
        if (mqtt.username.length > 0 && mqtt.password.length > 0) {
            msg.broker.username = mqtt.username;
            msg.broker.password = mqtt.password;
        }

        msg.broker.force = true;
        msg.action = 'connect';
        node.status({fill:"green",shape:"ring",text:"settings ok"});

        node.send(RED.util.cloneMessage(msg));

        delete msg.broker;
        msg.action = 'subscribe';
        msg.payload = '';

        // DKNR commands: topic / set / nuki / id / entity
        msg.topic = [mqtt.topic, 'set', source, '#'].join('/');
        node.send(RED.util.cloneMessage(msg));

        // Nuki Smart Lock 3.0/4.0 native MQTT API: nuki / id / key
        if (mqtt.nukimqtt === true) {
            msg.topic = 'nuki/+/+';
            node.send(RED.util.cloneMessage(msg));
        }

    } else {
        global.set('mqtt.enabled', false, 'default');
        node.status({ fill: "red", shape: "ring", text: "settings ko" });
    }
} else {
    msg.action = 'disconnect';

    node.send(msg);
}

return;

