    '2': 'Opener',
    '3': 'Smart Door',
    '4': 'Smart Lock 3.0/4.0'
};

// Nuki device family, anything that is not an opener is a smartlock
msg.payload.family = {
    '0': 'smartlock',
    '2': 'opener',
    '3': 'smartlock',
    '4': 'smartlock'
};

msg.payload.enum = {
    'state': {
        'smartlock': {
            '0': 'Non calibrée',
            '1': 'Verrouillée',
            '2': 'Déverrouillage',
