        },
        'opener': {
            '1': 'LOCKED',
            '3': 'UNLOCKED',
            '5': 'OPEN',
            '7': 'OPENING'
        }
    },
    // Home Assistant lock command to Nuki lock action
    'command': {
        'smartlock': { 'LOCK': 2, 'UNLOCK': 1, 'OPEN': 3 },
        'opener': { 'LOCK': 2, 'UNLOCK': 1, 'OPEN': 3 }
    }
};

const e = msg.payload.enum;

// control entry: [name, entity, group, type, unit, default value, options: {key: name}, ha type, ha state_class, ha device_class, device field]
msg.payload.control = {
    'smartlock': {
        'lock': ['Serrure', 'lock', 'command', 'enum', '', '', e.lock.smartlock, 'lock', '', '', 'state'],
        'action': ['Action', 'action', 'command', 'enum', '', '', e.action.smartlock, 'select', '', '', 'action'],
        'state': ['Etat', 'state', 'sensor', 'enum', '', '255', e.state.smartlock, 'sensor', '', 'enum', 'state'],
        'mode': ['Mode', 'mode', 'sensor', 'enum', '', '2', e.mode, 'sensor', '', 'enum', 'mode'],
        'batteryChargeState': ['Batterie', 'battery', 'sensor', 'number', '%', 0, {}, 'sensor', 'measurement', 'battery', 'batteryChargeState'],
        'batteryCritical': ['Batterie faible', 'batteryCritical', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', 'battery', 'batteryCritical'],
        'batteryCharging': ['Batterie en charge', 'batteryCharging', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', 'battery_charging', 'batteryCharging'],
        'keypadBatteryCritical': ['Batterie clavier faible', 'keypadBatteryCritical', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', 'battery', 'keypadBatteryCritical'],
        'doorsensorState': ['Capteur de porte', 'doorsensorState', 'sensor', 'enum', '', '255', e.doorsensorState, 'sensor', '', 'enum', 'doorsensorState'],
        'door': ['Porte ouverte', 'door', 'sensor', 'door', '', false, {}, 'binary_sensor', '', 'door', 'doorsensorState'],
        'doorsensorBatteryCritical': ['Batterie capteur faible', 'doorsensorBatteryCritical', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', 'battery', 'doorsensorBatteryCritical'],
        'lastAction': ['Dernière action', 'lastAction', 'sensor', 'text', '', '', {}, 'sensor', '', '', 'lastAction'],
        'timestamp': ['Mise à jour', 'timestamp', 'sensor', 'text', '', '', {}, 'sensor', '', 'timestamp', 'timestamp'],
        'firmware': ['Firmware', 'firmware', 'sensor', 'text', '', '', {}, 'sensor', '', '', 'firmware']
    },
    'opener': {
        'lock': ['Ouverture', 'lock', 'command', 'enum', '', '', e.lock.opener, 'lock', '', '', 'state'],
        'action': ['Action', 'action', 'command', 'enum', '', '', e.action.opener, 'select', '', '', 'action'],
        'state': ['Etat', 'state', 'sensor', 'enum', '', '255', e.state.opener, 'sensor', '', 'enum', 'state'],
        'mode': ['Mode', 'mode', 'sensor', 'enum', '', '2', e.mode, 'sensor', '', 'enum', 'mode'],
        'batteryCritical': ['Batterie faible', 'batteryCritical', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', 'battery', 'batteryCritical'],
        'ringactionState': ['Sonnette', 'ring', 'sensor', 'binary', '', false, {}, 'binary_sensor', '', 'sound', 'ringactionState'],
        'ringactionTimestamp': ['Dernier coup de sonnette', 'ringTimestamp', 'sensor', 'text', '', '', {}, 'sensor', '', 'timestamp', 'ringactionTimestamp'],
        'lastAction': ['Dernière action', 'lastAction', 'sensor', 'text', '', '', {}, 'sensor', '', '', 'lastAction'],
        'timestamp': ['Mise à jour', 'timestamp', 'sensor', 'text', '', '', {}, 'sensor', '', 'timestamp', 'timestamp'],
        'firmware': ['Firmware', 'firmware', 'sensor', 'text', '', '', {}, 'sensor', '', '', 'firmware']
    }
};

return msg;

// Prepare Nuki Bridge /list queries (cached device states, no Bluetooth wake up)
// msg.topic can be a bridge host to query only this bridge

const crypto = global.get('crypto');
const bridges = global.get('bridges', 'default') || {};

function base(b) {
    return 'http://' + b.host + ':' + (b.port || 8080);
}

function auth(b) {
    if (b.hashed === true && crypto) {
        const ts = new Date().toISOString().slice(0, 19) + 'Z';
        const rnr = Math.floor(Math.random() * 65535);
        const hash = crypto.createHash('sha256').update(ts + ',' + rnr + ',' + b.token).digest('hex');

        return 'ts=' + encodeURIComponent(ts) + '&rnr=' + rnr + '&hash=' + hash;
    }

    return 'token=' + encodeURIComponent(b.token || '');
}

for (const host in bridges) {
    if (typeof msg.topic === 'string' && msg.topic !== '' && typeof bridges[msg.topic] === 'object' && msg.topic !== host) {

        continue;
    }

    node.send({
        'topic': host,
        'url': base(bridges[host]) + '/list?' + auth(bridges[host])
    });
}

return;

// Parse Nuki Bridge /list response and store devices in memory
// output 1: one message per device (topic = device id) / output 2: new device found

const describe = global.get('describe', 'memoryOnly') || {};
const bridges = global.get('bridges', 'default') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const host = msg.topic;

if (!Array.isArray(msg.payload) || typeof bridges[host] !== 'object') {
    node.status({ fill: 'red', shape: 'ring', text: host + ' : réponse invalide' });

    return;
}

let added = false;
let count = 0;

for (const item of msg.payload) {
    if (typeof item !== 'object' || item === null || typeof item.nukiId !== 'number') {

        continue;
    }

    // Nuki ID in hexadecimal as printed on the device and used by Nuki MQTT API
    const id = item.nukiId.toString(16).toUpperCase().padStart(8, '0');
    const type = Number(item.deviceType || 0);
    const previous = devices[id] || {};

    if (typeof devices[id] !== 'object') {
        added = true;
    }

    devices[id] = {
        ...previous,
        ...(item.lastKnownState || {}),
        'id': id,
        'nukiId': item.nukiId,
        'deviceType': type,
        'family': (describe.family || {})[String(type)] || 'smartlock',
        'model': (describe.model || {})[String(type)] || 'Nuki (' + type + ')',
        'name': item.name || previous.name || id,
        'firmware': item.firmwareVersion || previous.firmware,
        'source': 'bridge',
        'bridge': host,
        'updated': Date.now()
    };
    count++;

    node.send([{ 'topic': id, 'payload': id }, null]);
}

global.set('devices', devices, 'memoryOnly');

node.status({ fill: 'green', shape: 'dot', text: (bridges[host].name || host) + ' : ' + count + ' appareil(s)' });

if (added) {
    node.send([null, { 'topic': 'discovery', 'payload': '' }]);
}

return;

// Bridge unreachable or invalid token

const bridges = global.get('bridges', 'default') || {};
const bridge = bridges[msg.topic] || {};
const name = bridge.name || msg.topic || '';

if (msg.statusCode === 401 || msg.statusCode === 403) {
    msg.payload = 'Bridge ' + name + ' : jeton refusé (vérifier le jeton ou l\'horloge si le jeton chiffré est activé)';
} else {
    msg.payload = 'Bridge ' + name + ' : injoignable';
}

node.status({ fill: 'red', shape: 'ring', text: msg.payload });

return msg;

// Publish changed values of a device to DKNR MQTT topic: topic / get / nuki / id / entity

const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
const describe = global.get('describe', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const source = 'nuki';
const id = msg.topic;
const dev = devices[id];

if (!enabled || topic === '' || typeof dev !== 'object') {

    return;
}

function value(dev, def) {
    const raw = dev[def[10]];
    if (raw === undefined || raw === null || raw === '') {

        return undefined;
    }
    if (def[3] === 'enum') {

        return def[6][String(raw)];
    }
    if (def[3] === 'binary') {

        return raw === true || raw === 1 ? 'ON' : 'OFF';
    }
    if (def[3] === 'door') {

        return raw === 3 ? 'ON' : (raw === 2 ? 'OFF' : undefined);
    }

    return raw;
}

const control = (describe.control || {})[dev.family] || {};

for (const k in control) {
    const v = value(dev, control[k]);
    if (v === undefined) {

        continue;
    }

    const last = 'last["' + id + '_' + control[k][1] + '"]';
    if (flow.get(last, 'memoryOnly') === v) {

        continue;
    }
    flow.set(last, v, 'memoryOnly');

    node.send({
        'topic': [topic, 'get', source, id, control[k][1]].join('/'),
        'payload': v,
        'qos': 0,
        'retain': true
    });
}

return;

// Nuki Bridge callback: instant state change of a known device
// payload: {nukiId, deviceType, mode, state, stateName, batteryCritical, ...}

let data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {

        return;
    }
}

if (typeof data !== 'object' || data === null || typeof data.nukiId !== 'number') {

    return;
}

const devices = global.get('devices', 'memoryOnly') || {};
const id = data.nukiId.toString(16).toUpperCase().padStart(8, '0');

// Unknown device, it will be added on next bridge query
if (typeof devices[id] !== 'object') {

    return;
}

const { nukiId, deviceType, ...state } = data;

devices[id] = {
    ...devices[id],
    ...state,
    'updated': Date.now()
};

global.set('devices', devices, 'memoryOnly');

node.status({ fill: 'green', shape: 'dot', text: id + ' - ' + (state.stateName || state.state) });

return { 'topic': id, 'payload': id };

// Read callbacks registered on bridges having a callback URL

const crypto = global.get('crypto');
const bridges = global.get('bridges', 'default') || {};

function base(b) {
    return 'http://' + b.host + ':' + (b.port || 8080);
}

function auth(b) {
    if (b.hashed === true && crypto) {
        const ts = new Date().toISOString().slice(0, 19) + 'Z';
        const rnr = Math.floor(Math.random() * 65535);
        const hash = crypto.createHash('sha256').update(ts + ',' + rnr + ',' + b.token).digest('hex');

        return 'ts=' + encodeURIComponent(ts) + '&rnr=' + rnr + '&hash=' + hash;
    }

    return 'token=' + encodeURIComponent(b.token || '');
}

for (const host in bridges) {
    if (typeof bridges[host].callback !== 'string' || bridges[host].callback === '') {

        continue;
    }

    node.send({
        'topic': host,
        'url': base(bridges[host]) + '/callback/list?' + auth(bridges[host])
    });
}

return;

// Register callback URL on bridge if missing
// output 1: bridge http query / output 2: notification

const crypto = global.get('crypto');
const bridges = global.get('bridges', 'default') || {};
const b = bridges[msg.topic];

function base(b) {
    return 'http://' + b.host + ':' + (b.port || 8080);
}

function auth(b) {
    if (b.hashed === true && crypto) {
        const ts = new Date().toISOString().slice(0, 19) + 'Z';
        const rnr = Math.floor(Math.random() * 65535);
        const hash = crypto.createHash('sha256').update(ts + ',' + rnr + ',' + b.token).digest('hex');

        return 'ts=' + encodeURIComponent(ts) + '&rnr=' + rnr + '&hash=' + hash;
    }

    return 'token=' + encodeURIComponent(b.token || '');
}

if (typeof b !== 'object' || typeof b.callback !== 'string' || b.callback === '') {

    return;
}

let data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        data = {};
    }
}

if (msg.statusCode !== 200 || typeof data !== 'object' || data === null || !Array.isArray(data.callbacks)) {
    node.status({ fill: 'red', shape: 'ring', text: b.name + ' : lecture impossible' });

    return [null, { 'payload': 'Bridge ' + b.name + ' : impossible de lire les callbacks' }];
}

if (data.callbacks.some(c => c.url === b.callback)) {
    node.status({ fill: 'green', shape: 'dot', text: b.name + ' : callback ok' });

    return;
}

if (data.callbacks.length >= 3) {
    node.status({ fill: 'red', shape: 'ring', text: b.name + ' : 3 callbacks' });

    return [null, { 'payload': 'Bridge ' + b.name + ' : 3 callbacks déjà enregistrés, supprimez-en un' }];
}

return [{
    'topic': msg.topic,
    'url': base(b) + '/callback/add?url=' + encodeURIComponent(b.callback) + '&' + auth(b)
}, null];

// Bridge /callback/add response

const bridges = global.get('bridges', 'default') || {};
const name = (bridges[msg.topic] || {}).name || msg.topic;

let data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        data = {};
    }
}

if (msg.statusCode === 200 && typeof data === 'object' && data !== null && data.success === true) {
    node.status({ fill: 'green', shape: 'dot', text: name + ' : callback ajouté' });

    return;
}

node.status({ fill: 'red', shape: 'ring', text: name + ' : callback refusé' });

return { 'payload': 'Bridge ' + name + ' : callback refusé' + (data && data.message ? ' (' + data.message + ')' : '') };

// Nuki Smart Lock 3.0/4.0 native MQTT API: nuki / <nuki id hex> / <key>
// output 1: device updated (topic = device id) / output 2: new device found

if (global.get('mqtt.nukimqtt', 'default') !== true) {

    return;
}

const path = msg.topic.split('/');
if (path.length !== 3 || path[0] !== 'nuki') {

    return;
}

const allowed = [
    'deviceType', 'name', 'firmware', 'mode', 'state',
    'batteryCritical', 'batteryChargeState', 'batteryCharging', 'keypadBatteryCritical',
    'doorsensorState', 'doorsensorBatteryCritical',
    'ringactionTimestamp', 'ringactionState',
    'serverConnected', 'connected', 'timestamp',
    'lockActionEvent', 'commandResponse'
];

const id = path[1].toUpperCase();
const key = path[2];

if (!/^[0-9A-F]{1,8}$/.test(id) || !allowed.includes(key)) {

    return;
}

const describe = global.get('describe', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const e = describe.enum || {};

let value = msg.payload;
if (Buffer.isBuffer(value)) {
    value = value.toString();
}
if (typeof value === 'string') {
    value = value.trim();
    if (value === 'true' || value === 'false') {
        value = value === 'true';
    } else if (!['name', 'firmware', 'timestamp', 'ringactionTimestamp', 'lockActionEvent'].includes(key) && value !== '' && !isNaN(value)) {
        value = Number(value);
    }
}

let added = false;
let dev = devices[id];
if (typeof dev !== 'object') {
    added = true;
    dev = {
        'id': id,
        'nukiId': parseInt(id, 16),
        'deviceType': 4,
        'family': 'smartlock',
