const describe = global.get('describe', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const bridges = global.get('bridges', 'default') || {};

function base(b) {
    return 'http://' + b.host + ':' + (b.port || 8080);
}

function auth(b) {
    if (b.hashed === true && crypto) {
        const ts = new Date().toISOString().slice(0, 19) + 'Z';
        const rnr = Math.floor(Math.random() * 65535);
        const hash = crypto.createHash('sha256').update(ts + ',' + rnr + ',' + b.token).digest('hex');

        return 'ts=' + encodeURIComponent(ts) + '&rnr=' + rnr + '&hash=' + hash;
    }

    return 'token=' + encodeURIComponent(b.token || '');
}

const id = (msg.payload || {}).id;
const action = Number((msg.payload || {}).action);
const dev = devices[id];

if (typeof dev !== 'object' || typeof ((describe.enum.action || {})[dev.family] || {})[String(action)] !== 'string') {
    msg.payload = 'Ordre non traité';

    return [null, null, msg, null];
}

// keep last requested action
dev.action = action;
devices[id] = dev;
global.set('devices', devices, 'memoryOnly');

node.status({ fill: 'blue', shape: 'dot', text: dev.name + ' - ' + describe.enum.action[dev.family][String(action)] });

if (dev.source === 'mqtt') {

    return [null, {
        'topic': 'nuki/' + id + '/lockAction',
        'payload': action,
        'qos': 2,
        'retain': false
    }, null, { 'topic': id, 'payload': id }];
}

const bridge = bridges[dev.bridge];
if (typeof bridge !== 'object') {
    msg.payload = 'Bridge de ' + dev.name + ' introuvable';

    return [null, null, msg, null];
}

return [{
    'topic': dev.bridge,
    'id': id,
    'url': base(bridge) + '/lockAction?nukiId=' + dev.nukiId + '&deviceType=' + dev.deviceType + '&action=' + action + '&nowait=1&' + auth(bridge)
}, null, null, { 'topic': id, 'payload': id }];

